#!/bin/sh
# The offline sources of the terminal engine for a Flatpak build: which Ghostty commit the engine crate pins, and which
# Zig packages the engine build really fetches, each with a sha256 computed from two separate downloads.
#
#   sh scripts/flatpak-zig-sources.sh pin
#   sh scripts/flatpak-zig-sources.sh sources <list-file> [<scratch-dir>]
#
# Both files it writes are GENERATED. They are tool output, not hand-written, and the owner may regenerate them at any
# time with this script (scripts/build-flatpak.sh --engine-offline runs both steps). Do not edit them by hand.
#
# `pin` reads the Ghostty commit from the `GHOSTTY_COMMIT` constant of the build script of the engine crate
# (libghostty-vt-sys) in the cargo git checkout that Cargo.lock names, so the commit can never drift from what the app
# builds, and writes it with the revision of the engine crate to packaging/flatpak/generated/ghostty-pin.txt. The checkout
# is looked for below $CARGO_HOME (default ~/.cargo); run `cargo fetch --locked` once if it is not there.
#
# `sources` takes the list of package directories that an engine build with an EMPTY scratch Zig cache fetched (Zig 0.17
# unpacks them into the `zig-pkg/` folder of the project, one name per line: the file that scripts/build-flatpak.sh
# --engine-offline writes).
# Of the 37 packages that Ghostty lists in its build.zig.zon.json, the library build uses few, so only the listed ones are
# kept. Each is looked up in Ghostty's own build.zig.zon.json at the pinned commit (fetched from the raw GitHub address
# of the pin); a name that file does not know is an error, never a guess. Every tarball is downloaded twice into the
# scratch folder, both sha256 values must be equal, and packaging/flatpak/generated/zig-sources.json is written: a JSON
# array of Flatpak sources, `archive` for a tarball (url, sha256, strip-components as Zig unpacks it, dest) and `git` for
# an address that is a git repository (url, the 40-character commit, dest). Nothing without a hash or a commit is passed.
# Each dest is `zig-pkgs/<package hash>`, the directory name that Zig looks a package up by.
#
# It needs only sh, curl, jq, tar and sha256sum or shasum, installs nothing, and writes only the two files and the scratch
# folder. Exit status: 0 done, 1 a download, a check or a lookup failed, 2 a tool is missing or the usage is wrong.

here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
generated="$root/packaging/flatpak/generated"

die() {
    echo "flatpak-zig-sources: $*" >&2
    exit 1
}

usage() {
    echo "usage: sh scripts/flatpak-zig-sources.sh pin | sources <list-file> [<scratch-dir>]" >&2
    exit 2
}

for tool in curl jq tar; do
    command -v "$tool" >/dev/null 2>&1 || {
        echo "flatpak-zig-sources: $tool is missing" >&2
        exit 2
    }
done
if command -v sha256sum >/dev/null 2>&1; then
    sha256_of() { sha256sum "$1" | cut -d' ' -f1; }
elif command -v shasum >/dev/null 2>&1; then
    sha256_of() { shasum -a 256 "$1" | cut -d' ' -f1; }
else
    echo "flatpak-zig-sources: neither sha256sum nor shasum is there" >&2
    exit 2
fi

is_hex() { # is_hex <length> <text>
    [ "${#2}" = "$1" ] && [ -z "$(printf '%s' "$2" | tr -d '0-9a-f')" ]
}

fetch() { # fetch <url> <file>
    curl --proto '=https' --tlsv1.2 -fsSL --retry 3 -o "$2" "$1" || die "the download of $1 failed"
}

# The engine crate's revision, as Cargo.lock names it, and the checkout of it in the cargo home.
engine_revision() {
    rev=$(awk '
        /^name = "libghostty-vt-sys"$/ { found = 1; next }
        found && /^source = / { sub(/^.*#/, ""); sub(/".*$/, ""); print; exit }
    ' "$root/Cargo.lock")
    is_hex 40 "$rev" || die "Cargo.lock names no 40-character revision for libghostty-vt-sys"
    printf '%s\n' "$rev"
}

engine_build_script() { # engine_build_script <revision>
    short=$(printf '%s' "$1" | cut -c1-7)
    for candidate in "${CARGO_HOME:-$HOME/.cargo}"/git/checkouts/libghostty-rs-*/"$short"/crates/libghostty-vt-sys/build.rs; do
        if [ -f "$candidate" ]; then
            printf '%s\n' "$candidate"
            return 0
        fi
    done
    die "the cargo checkout of the engine crate $short is not below ${CARGO_HOME:-$HOME/.cargo}: run \`cargo fetch --locked\`"
}

constant() { # constant <name> <build script>: the value of `const NAME: &str = "value";`
    sed -n "s/^const $1: &str = \"\\([^\"]*\\)\";/\\1/p" "$2" | head -n 1
}

pin() {
    revision=$(engine_revision) || exit 1
    script=$(engine_build_script "$revision") || exit 1
    commit=$(constant GHOSTTY_COMMIT "$script")
    repo=$(constant GHOSTTY_REPO "$script")
    is_hex 40 "$commit" || die "no 40-character GHOSTTY_COMMIT in $script"
    case "$repo" in https://github.com/*) ;; *) die "unexpected GHOSTTY_REPO in $script: $repo" ;; esac
    mkdir -p "$generated" || exit 1
    {
        echo "# GENERATED by scripts/flatpak-zig-sources.sh pin: do not edit by hand. The owner may regenerate it with"
        echo "# \`sh scripts/flatpak-zig-sources.sh pin\` (or scripts/build-flatpak.sh --engine-offline)."
        echo "# The Ghostty commit is the GHOSTTY_COMMIT constant of the engine crate's build script, in the checkout that"
        echo "# Cargo.lock names, so it cannot drift from what the app builds."
        echo "ghostty-commit=$commit"
        echo "ghostty-repository=$repo"
        echo "libghostty-rs-revision=$revision"
    } >"$generated/ghostty-pin.txt.new" || exit 1
    mv "$generated/ghostty-pin.txt.new" "$generated/ghostty-pin.txt" || exit 1
    echo "flatpak-zig-sources: ghostty $commit (engine crate $revision)"
}

# Zig unpacks a tarball and drops the one directory that holds everything (the "root directory"); a tarball without
# one is unpacked as it is. Print 1 when the entries all share one top directory, else 0.
strip_components() { # strip_components <tarball>
    tops=$(tar -tf "$1" | sed 's#^\./##' | awk -F/ '$1 != "" && $1 != "." { print $1 }' | sort -u)
    [ -n "$tops" ] || die "$1 lists no entries"
    if [ "$(printf '%s\n' "$tops" | wc -l | tr -d ' ')" = 1 ] && tar -tf "$1" | sed 's#^\./##' | grep -q "^$tops/."; then
        echo 1
    else
        echo 0
    fi
}

archive_type() { # archive_type <url>
    case "$1" in
        *.tar.gz | *.tgz) echo tar-gzip ;;
        *.tar.xz) echo tar-xz ;;
        *.tar.zst) echo tar-zst ;;
        *) die "an archive type this tool does not know: $1" ;;
    esac
}

sources() {
    [ $# -ge 1 ] && [ $# -le 2 ] || usage
    list=$1
    scratch=${2:-"$root/target/flatpak-engine/scratch"}
    [ -f "$list" ] || die "the list file $list does not exist"
    [ -f "$generated/ghostty-pin.txt" ] || die "run \`sh scripts/flatpak-zig-sources.sh pin\` first"
    commit=$(sed -n 's/^ghostty-commit=//p' "$generated/ghostty-pin.txt")
    repo=$(sed -n 's/^ghostty-repository=//p' "$generated/ghostty-pin.txt")
    is_hex 40 "$commit" || die "ghostty-pin.txt holds no 40-character commit"

    mkdir -p "$scratch/one" "$scratch/two" || exit 1
    zon="$scratch/build.zig.zon.json"
    raw="https://raw.githubusercontent.com/${repo#https://github.com/}"
    raw=${raw%.git}
    fetch "$raw/$commit/build.zig.zon.json" "$zon"
    jq -e 'type == "object" and length > 0' "$zon" >/dev/null || die "build.zig.zon.json is not a list of packages"
    total=$(jq 'length' "$zon")

    entries="$scratch/entries"
    : >"$entries"
    used=0
    # sort -u: the order of the file is the order of the output, so a regeneration gives the same file.
    for name in $(sort -u "$list"); do
        case "$name" in *[!A-Za-z0-9_.-]* | "" | -* | .*) die "an odd package name in the list: $name" ;; esac
        jq -e --arg k "$name" 'has($k)' "$zon" >/dev/null ||
            die "the package $name was fetched by the build but is not in Ghostty's build.zig.zon.json at $commit: no pinned hash, not passed"
        url=$(jq -r --arg k "$name" '.[$k].url' "$zon")
        case "$url" in
            git+https://*#*)
                address=${url#git+}
                repo_url=${address%%#*}
                pinned=${address##*#}
                is_hex 40 "$pinned" || die "the git address of $name has no 40-character commit: $url"
                jq -n --arg url "$repo_url" --arg commit "$pinned" --arg dest "zig-pkgs/$name" \
                    '{type: "git", url: $url, commit: $commit, dest: $dest}' >>"$entries" || exit 1
                echo "flatpak-zig-sources: $name: git $pinned"
                ;;
            https://*)
                fetch "$url" "$scratch/one/$name"
                fetch "$url" "$scratch/two/$name"
                first=$(sha256_of "$scratch/one/$name")
                second=$(sha256_of "$scratch/two/$name")
                is_hex 64 "$first" || die "no sha256 for $name"
                [ "$first" = "$second" ] || die "two downloads of $url differ ($first, $second): not passed"
                strip=$(strip_components "$scratch/one/$name") || exit 1
                kind=$(archive_type "$url") || exit 1
                jq -n --arg url "$url" --arg sha "$first" --arg dest "zig-pkgs/$name" --arg kind "$kind" --argjson strip "$strip" \
                    '{type: "archive", "archive-type": $kind, url: $url, sha256: $sha, "strip-components": $strip, dest: $dest}' \
                    >>"$entries" || exit 1
                echo "flatpak-zig-sources: $name: sha256 $first (two downloads agree)"
                ;;
            *) die "an address that is neither https nor git+https for $name: $url" ;;
        esac
        used=$((used + 1))
    done
    [ "$used" -ge 1 ] || die "the list names no package"
    mkdir -p "$generated" || exit 1
    jq -s '.' "$entries" >"$generated/zig-sources.json.new" || exit 1
    mv "$generated/zig-sources.json.new" "$generated/zig-sources.json" || exit 1
    echo "flatpak-zig-sources: $used of the $total packages of Ghostty's list are used; wrote packaging/flatpak/generated/zig-sources.json"
}

case "${1:-}" in
    pin)
        [ $# -eq 1 ] || usage
        pin
        ;;
    sources)
        shift
        sources "$@"
        ;;
    *) usage ;;
esac
